def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def strict_json(raw):
    depth = 0
    quoted = escaped = False
    for byte in raw:
        if quoted:
            if escaped:
                escaped = False
            elif byte == 92:
                escaped = True
            elif byte == 34:
                quoted = False
        elif byte == 34:
            quoted = True
        elif byte in (91, 123):
            depth += 1
            require(depth <= 64, 'Глубина JSON превышена')
        elif byte in (93, 125):
            depth -= 1
            require(depth >= 0, 'Неверная вложенность JSON')
    require(not quoted and depth == 0, 'Незавершённый JSON')
    def pairs(items):
        result = {}
        for key, value in items:
            require(key not in result, 'Повтор ключа JSON')
            result[key] = value
        return result
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=lambda value: (_ for _ in ()).throw(ValueError('Недопустимая константа JSON')))


def load_both(args):
    specs = [(args.report, args.report_size, args.report_sha256), (args.materials, args.materials_size, args.materials_sha256)]
    for _, size, sha in specs:
        require(type(size) is int and 0 <= size <= MAX_INPUT and HEX.fullmatch(sha) is not None, 'Неверный pin входа')
    with safe.evidence_file(specs[0][0]) as first, safe.evidence_file(specs[1][0]) as second:
        files = (first, second)
        try:
            # Оба исходных файла закрепляются до любого разбора любого JSON.
            for f, (_, size, sha) in zip(files, specs):
                safe.checked(f, size, sha)
            raw = []
            for f, (_, size, sha) in zip(files, specs):
                data = f.read(size + 1)
                require(len(data) == size and digest(data) == sha, 'Bytes входа не совпадают с pin')
                raw.append(data)
            parsed = [strict_json(data) for data in raw]
        finally:
            errors = []
            for f, (_, size, sha) in zip(files, specs):
                try:
                    safe.checked(f, size, sha)
                except Exception as exc:
                    errors.append(str(exc))
            if errors:
                raise ValueError('Повторная проверка входов: ' + '; '.join(errors))
    return parsed


def partition_paragraph(text, line_start, byte_start):
    """Непрерывные UTF-8 фрагменты без потерь; сначала границы строк."""
    chunks = []
    pieces = text.splitlines(keepends=True)
    buffer = ''
    buffer_bytes = 0
    offset = byte_start
    line = line_start
    chunk_line = line
    line_breaks = ('\n', '\r', '\v', '\f', '\x1c', '\x1d', '\x1e', '\x85', '\u2028', '\u2029')
    def flush():
        nonlocal buffer, buffer_bytes, offset, chunk_line
        if buffer:
            chunks.append({'text': buffer, 'byte_start': offset, 'byte_end': offset + buffer_bytes, 'line_start': chunk_line, 'line_end': line - 1 if buffer.endswith(line_breaks) else line})
            offset += buffer_bytes
            buffer, buffer_bytes = '', 0
            chunk_line = line
    for piece in pieces:
        size = len(piece.encode('utf-8'))
        if buffer and buffer_bytes + size > MAX_EXCERPT:
            flush()
        if size <= MAX_EXCERPT:
            buffer += piece
            buffer_bytes += size
        else:
            # В одной длинной строке деление идёт по символам, не по UTF-8 bytes.
            for char in piece:
                n = len(char.encode('utf-8'))
                if buffer_bytes + n > MAX_EXCERPT:
                    flush()
                buffer += char
                buffer_bytes += n
        if piece.endswith(line_breaks):
            line += 1
    flush()
    for index, chunk in enumerate(chunks):
        chunk['continuation_before'] = index > 0
        chunk['continuation_after'] = index + 1 < len(chunks)
    return chunks


def passages(raw):
    require(len(raw) <= MAX_TEXT, 'Материал превышает предел 10 MB')
    try:
        text = raw.decode('utf-8', 'strict')
    except UnicodeDecodeError as exc:
        boundary = exc.reason == 'unexpected end of data' and exc.end == len(raw)
        if boundary:
            partial = passages(raw[:exc.start])
            partial['encoding'] = 'incomplete_codepoint_at_boundary'
            partial['decode_error_bytes'] = [exc.start, exc.end]
            return partial
        return {'encoding': 'unknown', 'decode_error_bytes': [exc.start, exc.end], 'families': [], 'clauses': [], 'references': [], 'unclassified_ranges': []}
    lines = text.splitlines(keepends=True)
    require(len(lines) <= MAX_LINES, 'Слишком много строк материала')
    offsets = [0]
    for line in lines:
        offsets.append(offsets[-1] + len(line.encode('utf-8')))
    require(offsets[-1] == len(raw), 'Несовпадение offsets материала')
    normalized_text = re.sub(r'\s+', ' ', text)
    families = [name for name, pattern in FAMILY_RE.items() if pattern.search(normalized_text)]
    clauses, references, unclassified = [], [], []
    # Абзацы дают контекст переносов строк; пустые строки сохраняются в диапазонах.
    start = 0
    while start < len(lines):
        end = start + 1
        while end < len(lines) and lines[end - 1].strip() and lines[end].strip():
            end += 1
        paragraph = ''.join(lines[start:end])
        normalized = re.sub(r'\s+', ' ', paragraph)
        labels = [name for name, pattern in TERM_RE.items() if pattern.search(normalized)]
        span = {'line_start': start + 1, 'line_end': end, 'byte_start': offsets[start], 'byte_end': offsets[end]}
        modalities = []
        if PERMISSION.search(normalized):
            modalities.append('permission_observed')
        if REQUIREMENT.search(normalized):
            modalities.append('requirement_or_condition_observed')
        if PROHIBITION.search(normalized):
            modalities.append('prohibition_or_limit_observed')
        if labels or modalities:
            chunks = partition_paragraph(paragraph, start + 1, offsets[start])
            require(chunks and chunks[0]['byte_start'] == offsets[start] and chunks[-1]['byte_end'] == offsets[end], 'Неверное разделение абзаца')
            clauses.extend({**chunk, 'kinds': labels, 'modalities': modalities, 'paragraph_line_start': start + 1, 'paragraph_line_end': end, 'paragraph_byte_start': offsets[start], 'paragraph_byte_end': offsets[end], 'classification_scope': 'whole_paragraph'} for chunk in chunks)
        elif paragraph.strip():
            stripped = paragraph.strip()
            role = 'copyright_or_attribution' if re.search(r'copyright|©|\(c\)', stripped, re.I) else ('heading_candidate' if len(stripped) <= 120 and '\n' not in stripped else 'unclassified_narrative_or_condition')
            unclassified.append({**span, 'role': role})
        for match in REFERENCE.finditer(paragraph):
            before = paragraph[:match.start()]
            line_index = start + len(before.splitlines())
            # splitlines считает незавершённую строку; её номер корректируется.
            if before and not before.endswith(('\n', '\r')):
                line_index -= 1
            byte_start = offsets[start] + len(before.encode('utf-8'))
            is_url = bool(re.search(r'https?://\S*' + re.escape(match.group(1)), normalized, re.I))
            conditional_notice = match.group(1).upper() == 'NOTICE' and bool(re.search(r'\bif\b.{0,120}\b(?:includes?|contains?)\b.{0,80}\bnotice\b', normalized, re.I))
            references.append({'name': match.group(1).rstrip('.'), 'line': line_index + 1, 'byte_start': byte_start, 'byte_end': byte_start + len(match.group(1).rstrip('.').encode('utf-8')), 'context_byte_start': offsets[start], 'context_byte_end': offsets[end], 'external_url': is_url, 'conditional_notice': conditional_notice})
            require(len(references) <= MAX_REFS, 'Слишком много ссылок в материале')
        start = end
    return {'encoding': 'utf-8', 'families': families, 'clauses': clauses, 'references': references, 'unclassified_ranges': unclassified}


def resolve_reference(reference, source_path, inventory, raw, apache_rule):
    name = reference['name'].rstrip('.')
    reference = {**reference, 'name': name}
    basename = name.rsplit('/', 1)[-1]
    context = re.sub(r'\s+', ' ', raw[reference['context_byte_start']:reference['context_byte_end']].decode('utf-8', 'strict'))
    if reference['external_url']:
        return {**reference, 'matches': [], 'resolution': 'external_url_not_visited'}
    if basename.upper() == 'NOTICE' and (reference['conditional_notice'] or apache_rule):
        present = [p for p in inventory if p.rsplit('/', 1)[-1].upper() == 'NOTICE']
        return {**reference, 'matches': present, 'resolution': 'license_rule_conditional', 'scope': 'Условие воспроизведения применимо к существующему NOTICE; текст лицензии не утверждает наличие NOTICE у данного проекта.'}
    if '/' not in name and not re.search(r'[-._]', basename) and not re.search(r'\b(?:file|files|see|refer(?:ence)?|contained in|named|called)\b.{0,100}\b' + re.escape(name) + r'\b|\b' + re.escape(name) + r'\b.{0,30}\bfile\b', context, re.I):
        return {**reference, 'matches': [], 'resolution': 'uncertain_generic_word'}
    # Обычное слово license не превращается в утверждение об отсутствующем файле.
    if basename != basename.upper() and '/' not in name:
        return {**reference, 'matches': [], 'resolution': 'uncertain_generic_word'}
    parent = pathlib.PurePosixPath(source_path).parent
    # Нормализация проводится только над текстом ссылки, без доступа к файловой системе.
    parts = list(parent.parts)
    for part in name.split('/'):
        if part == '.':
            continue
        if part == '..':
            if parts:
                parts.pop()
        else:
            parts.append(part)
    relative = '/'.join(parts)
    exact = [p for p in inventory if p == relative]
    basename = [p for p in inventory if p.rsplit('/', 1)[-1].casefold() == name.rsplit('/', 1)[-1].casefold()]
    matches = exact if exact else basename
    return {**reference, 'relative_candidate': relative, 'matches': matches, 'resolution': 'exact_relative' if exact else ('unique_basename' if len(matches) == 1 else 'ambiguous' if matches else 'missing_in_archive_inventory')}


def branches(expression):
    if not isinstance(expression, str) or not expression:
        return []
    # Не интерпретируем синтаксис SPDX и не заменяем исторический slash на OR.
    tokens = [m.group() for m in TOKEN.finditer(expression)]
    result = []
    after_with = False
    for token in tokens:
        if token == 'WITH':
            after_with = True
        elif token in ('OR', 'AND', '(', ')', '/'):
            continue
        else:
            result.append({'token': token, 'role': 'with_exception' if after_with else 'license_branch'})
            after_with = False
    return result


def family_for_branch(branch, families):
    key = branch.lower()
    return [f for f in families if key == f.lower() or key.startswith(f.lower() + '-') or (f == 'BSD' and key.startswith('bsd-')) or (f == 'Unicode' and key.startswith('unicode-'))]


def research(report, data):
    require(isinstance(report, dict) and isinstance(data, dict) and isinstance(report.get('components'), list) and isinstance(data.get('materials'), list), 'Неверная структура входа')
    components = {}
    for component in report['components']:
        path = component['archive_path']
        require(path not in components, 'Повтор архива')
        components[path] = {'name': component['name'], 'version': component['version'], 'archive_path': path, 'archive_sha256': component['archive_sha256'], 'manifest': component['manifest'], 'inventory': component['inventory'], 'materials': [], 'blockers': []}
    templates = {}
    retained_bytes = {}
    total_clauses = 0
    seen = set()
    for item in data['materials']:
        archive, path = item['archive'], item['path']
        require(archive in components and (archive, path) not in seen, 'Неизвестный или повторный материал')
        seen.add((archive, path))
        raw = base64.b64decode(item['bytes_base64'], validate=True)
        require(len(raw) == item['retained_size'] and digest(raw) == item['retained_sha256'], 'Повреждены сохранённые bytes')
        retention = item['retention']
        require(retention in ('full', 'prefix') and len(raw) <= item['size'], 'Неверное сохранение материала')
        if retention == 'full':
            require(len(raw) == item['size'] and digest(raw) == item['sha256'], 'Полный материал не совпадает с inventory')
        key = item['retained_sha256']
        binary_archive = raw.startswith(b'!<arch>\n')
        if binary_archive:
            template = {'encoding': 'binary_ar_archive', 'families': [], 'clauses': [], 'references': [], 'unclassified_ranges': []}
        elif key not in templates:
            template = passages(raw)
        else:
            template = templates[key]
        if key not in templates:
            total_clauses += len(template['clauses'])
            require(total_clauses <= MAX_CLAUSES, 'Превышен общий предел фрагментов')
            templates[key] = template
            retained_bytes[key] = raw
        template = templates[key]
        license_role = not binary_archive and bool(item.get('explicit_license_file') or re.match(r'^(?:LICEN[CS]E|COPYING|UNLICENSE|MPL|LGPL|GPL|MIT|APACHE)(?:$|[-._])', path.rsplit('/', 1)[-1], re.I))
        # marker_scan_not_conditions: kinds/modalities ниже — автоматический поиск,
        # а не содержательное чтение условий; условия строятся только из ручных span.
